<script setup lang="ts">
import{ref,computed,toRaw}from'vue';import type{Bootstrap}from'../lib/model';import{defaultIntelligence,type Intelligence,type ClientBrain}from'../lib/intelligence';import{api}from'../lib/api';import Icon from'./Icon.vue';import Toggle from'./ui/Toggle.vue';import Modal from'./ui/Modal.vue';
const props=defineProps<{state:Bootstrap;section:string}>();const emit=defineEmits<{refresh:[]}>();const config=ref<Intelligence>(structuredClone(toRaw(props.state.workspace.intelligence||defaultIntelligence())));const version=ref(props.state.version);const busy=ref(false),error=ref(''),notice=ref(''),modal=ref('');const source=ref({name:'',kind:'document',location:'',audience:'public',content:''});const key=ref(''),providerId=ref('');const brain=ref<ClientBrain>();const origins=ref(config.value.widget.allowedOrigins.join('\n'));const canEdit=computed(()=>['owner','admin'].includes(props.state.session.role));
const colors:Record<string,string>={forest:'#285d4b',indigo:'#505ba7',coral:'#ec6574',midnight:'#273444'};const headings:Record<string,[string,string]>={assistant:['Make your assistant your own.','A name, a voice, a trusted source, and clear limits.'],memory:['Context that remembers with care.','Collect useful history only when you choose. Keep facts separate from guesses.'],sources:['A foundation of trusted knowledge.','Register sources, review what they contain, and decide who can use them.'],widget:['A welcome that feels like you.','Create a distinctive chat experience for the people visiting your website.']};
const embed=computed(()=>`<script src="${location.origin}/widget.js" data-workspace="${props.state.workspace.id}" defer><\/script>`);
async function request(path:string,method:string,body:unknown){busy.value=true;error.value='';try{const r=await api(path,{method,body,workspace:props.state.workspace.id,version:version.value});if(r.version)version.value=r.version;emit('refresh');return r;}catch(e:any){error.value=e.message;throw e;}finally{busy.value=false;}}
async function save(){try{config.value.widget.allowedOrigins=origins.value.split(/\n|,/).map(s=>s.trim()).filter(Boolean);const{sources,brains,...settings}=config.value;await request('/intelligence','PATCH',settings);notice.value='Assistant preferences saved.';}catch{}}
function addProvider(){config.value.providers.push({id:crypto.randomUUID(),name:'My provider',provider:'openai',model:'',tasks:['reply'],credentialSet:false});}
function addPrompt(){config.value.prompts.push({id:crypto.randomUUID(),name:'New prompt',task:'reply',text:''});}
async function saveKey(){try{await request(`/intelligence/providers/${providerId.value}/key`,'POST',{key:key.value});key.value='';modal.value='';const p=config.value.providers.find(p=>p.id===providerId.value);if(p)p.credentialSet=true;notice.value='Provider credential encrypted and saved. Live execution is still disabled.';}catch{key.value='';}}
async function addSource(){try{await request('/intelligence/sources','POST',source.value);modal.value='';notice.value=source.value.kind==='document'?'Document text imported as a draft. Review and publish it in Knowledge.':'Source registered. No external data was fetched.';const b=await api('/bootstrap',{workspace:props.state.workspace.id});config.value.sources=b.workspace.intelligence.sources;version.value=b.version;}catch{}}
async function readDocument(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>32000){error.value='Import a text file of 32 KB or less.';return;}source.value.content=(await file.text()).slice(0,8000);if(!source.value.name)source.value.name=file.name;}
async function saveBrain(){if(!brain.value)return;try{await request('/intelligence/brain/'+brain.value.contactId,'PATCH',{summary:brain.value.summary,reviewed:brain.value.reviewed});modal.value='';notice.value='Customer profile saved. Exact token-budget checks still apply before model inclusion.';}catch{}}
async function copyEmbed(){try{await navigator.clipboard.writeText(embed.value);notice.value='Widget snippet copied.';}catch{notice.value='Select and copy the snippet below.';}}
function editBrain(value:ClientBrain){brain.value=structuredClone(toRaw(value));modal.value='brain';}
</script>
<template><div class="page-heading"><div><div class="greeting">{{section==='widget'?'YOUR BRAND, IN EVERY CONVERSATION':'INTELLIGENCE BY DESIGN'}}</div><h1>{{headings[section][0]}}</h1><p>{{headings[section][1]}}</p></div><button v-if="canEdit" class="button primary" :disabled="busy" @click="save"><Icon name="check" :size="16"/>Save preferences</button></div><p v-if="error" class="form-error mb-5" role="alert">{{error}}</p><p v-if="notice" class="success-banner" role="status">{{notice}}</p>
<template v-if="section==='assistant'"><div class="settings-layout"><section class="panel settings-form"><h2>Meet your assistant</h2><label>Assistant name<input v-model="config.assistantName" maxlength="60" :disabled="!canEdit"/></label><label>Communication style<select v-model="config.tone" :disabled="!canEdit"><option value="warm">Warm and helpful</option><option value="concise">Concise and direct</option><option value="formal">Professional and formal</option></select></label><label>Core instructions<textarea v-model="config.instructions" rows="7" maxlength="8000" :disabled="!canEdit"/><small>Instructions guide tone and answers. They cannot override server access policies or approve database actions.</small></label><label>AI funding mode<select v-model="config.mode" :disabled="!canEdit"><option value="hosted">Sahdev models · prepaid usage</option><option value="byok">My provider · no Sahdev token debit</option></select></label><label v-if="config.mode==='hosted'">Model offer ID<input v-model="config.modelOfferId" placeholder="Choose a model after the platform catalog is enabled" :disabled="!canEdit"/></label><label v-else>Default provider<select v-model="config.providerId" :disabled="!canEdit"><option value="">Select a connection</option><option v-for="p in config.providers" :key="p.id" :value="p.id">{{p.name}}</option></select></label></section><aside class="panel policy-guide"><div class="assistant-symbol">✳</div><h2>{{config.assistantName}}, with boundaries.</h2><p>Live generation is currently disabled. Your settings and prompt library are durable, but no provider request is made until activation and validation.</p><h3>Provider choice is explicit.</h3><p>BYOK never falls back to a Sahdev-paid credential. Feature entitlements, request limits and concurrency still apply.</p><h3>Useful context, not a bigger prompt.</h3><p>Published knowledge, recent messages, and optional reviewed customer memory form separate context sections. Untrusted content cannot grant permissions.</p></aside></div><div class="collection-toolbar no-border mt-7"><div><h2>Provider connections</h2><p class="muted text-xs mt-2">Use separate providers for replies, summaries, classification, or embeddings.</p></div><button v-if="canEdit" class="button secondary" @click="addProvider"><Icon name="plus" :size="16"/>Add BYOK connection</button></div><article v-for="p in config.providers" :key="p.id" class="panel config-card"><div class="form-grid"><label>Connection name<input v-model="p.name" :disabled="!canEdit"/></label><label>Provider<select v-model="p.provider" :disabled="!canEdit"><option>openai</option><option>anthropic</option><option>gemini</option><option>openrouter</option></select></label><label>Exact model ID<input v-model="p.model" :disabled="!canEdit"/></label><label>Assigned task<select v-model="p.tasks[0]" :disabled="!canEdit"><option value="reply">Conversation replies</option><option value="summary">Summaries</option><option value="classification">Classification</option><option value="embedding">Embeddings</option></select></label></div><div class="flex justify-between items-center mt-5"><span :class="['status',p.credentialSet?'open':'pending']">{{p.credentialSet?'Credential stored · unverified':'No credential stored'}}</span><button v-if="canEdit" class="text-action" @click="providerId=p.id;key='';modal='key'">{{p.credentialSet?'Replace credential':'Set credential'}} <Icon name="lock" :size="14"/></button></div></article><div v-if="!config.providers.length" class="empty-state panel compact"><Icon name="sparkles" :size="25"/><p>No provider connections yet. Save the connection before setting its credential.</p></div><div class="collection-toolbar no-border mt-7"><h2>Prompt library</h2><button v-if="canEdit" class="button secondary" @click="addPrompt"><Icon name="plus" :size="16"/>Add prompt</button></div><article v-for="p in config.prompts" :key="p.id" class="panel config-card"><div class="form-grid"><label>Prompt name<input v-model="p.name" :disabled="!canEdit"/></label><label>Task<input v-model="p.task" :disabled="!canEdit"/></label></div><label class="block text-xs muted mt-5">Instructions<textarea class="w-full mt-2" v-model="p.text" rows="3" maxlength="4000" :disabled="!canEdit"/></label></article></template>
<template v-else-if="section==='memory'"><div class="settings-layout"><section class="panel settings-form"><h2>A customer brain, with consent and limits.</h2><div class="setting-row"><div><strong>Collect interaction history</strong><p>When a ticket is resolved, save a timestamped extract of the customer’s messages. Extracts are clearly labeled drafts.</p></div><Toggle v-model="config.memory.collect" label="Collect interaction history" :disabled="!canEdit"/></div><div class="setting-row"><div><strong>Include reviewed profile</strong><p>Up to 200 tokens, including labels. A model-specific token counter must be available.</p></div><Toggle v-model="config.memory.includeProfile" label="Include customer profile" :disabled="!canEdit"/></div><div class="setting-row"><div><strong>Include reviewed timeline</strong><p>Up to 1,000 tokens across selected events, with timestamps and source references.</p></div><Toggle v-model="config.memory.includeTimeline" label="Include customer timeline" :disabled="!canEdit"/></div><label>Retention window (days)<input type="number" min="1" max="365" v-model.number="config.memory.retentionDays" :disabled="!canEdit"/></label></section><aside class="panel policy-guide"><Icon name="shield" :size="30"/><h2>Memory should be earned.</h2><p>Collection, profile inclusion, and timeline inclusion are independent choices. Turning off context does not erase stored history.</p><h3>Never guess a person.</h3><p>Keep factual preferences and support history with their sources. Do not infer sensitive traits, emotions, creditworthiness, or identity from a conversation.</p><h3>Exact budgets, or no memory.</h3><p>Optional memory is omitted when the selected model’s exact token counter is unavailable. Character counts are never presented as exact tokens. Live AI summaries are not generated while the provider is disabled.</p></aside></div><section class="panel mt-7"><div class="panel-heading mb-5"><div><h2>Customer memory records</h2><p>Visible to authorized staff. Never returned in customer portal responses.</p></div></div><div class="table-scroll"><table><thead><tr><th>Customer</th><th>Events</th><th>Profile review</th><th>Updated</th><th></th></tr></thead><tbody><tr v-for="b in config.brains" :key="b.contactId"><td>{{state.workspace.contacts.find(c=>c.id===b.contactId)?.name||'Customer'}}</td><td>{{b.events.length}}</td><td><span :class="['status',b.reviewed?'open':'pending']">{{b.reviewed?'Reviewed':'Draft'}}</span></td><td>{{new Date(b.updatedAt).toLocaleDateString('en-IN')}}</td><td><button class="text-action" @click="editBrain(b)">Review context <Icon name="arrow" :size="14"/></button></td></tr><tr v-if="!config.brains.length"><td colspan="5" class="table-empty">No memory collected. Enable collection, save preferences, then resolve a conversation.</td></tr></tbody></table></div></section></template>
<template v-else-if="section==='sources'"><div class="collection-toolbar no-border"><span class="pill sample"><Icon name="shield" :size="14"/>New sources start with no automatic AI access</span><button v-if="canEdit" class="button primary" @click="modal='source'"><Icon name="plus" :size="16"/>Add a data source</button></div><div class="source-types"><article class="panel"><Icon name="file" :size="25"/><h2>Documents & text</h2><p>Import text into a draft knowledge article. Review its audience before publishing.</p><span class="status open">Text import available</span></article><article class="panel"><Icon name="globe" :size="25"/><h2>Your website</h2><p>Register an HTTPS source. Remote ingestion requires the protected Go connector.</p><span class="status pending">Connector required</span></article><article class="panel"><Icon name="building" :size="25"/><h2>Business databases</h2><p>Inspect schema, review mappings, then authorize bounded typed operations.</p><span class="status pending">Go harness required</span></article></div><section class="panel mt-6"><div class="table-scroll"><table><thead><tr><th>Source</th><th>Type</th><th>Audience</th><th>Status</th></tr></thead><tbody><tr v-for="s in config.sources" :key="s.id"><td><strong>{{s.name}}</strong><small class="block muted">{{s.location||'Imported text'}}</small></td><td>{{s.kind}}</td><td><span class="pill subtle">{{s.audience}}</span></td><td>{{s.articleId?'Draft article created':'Registered · not fetched'}}</td></tr><tr v-if="!config.sources.length"><td class="table-empty" colspan="4">No sources registered. Your existing knowledge articles remain available.</td></tr></tbody></table></div></section><div class="panel policy-note"><Icon name="lock"/><p>Database passwords never belong in a prompt or URL. The Go harness uses named local connections, schema-only discovery, explicit column mappings, verified customer scope, bounded reads, and approval-bound write proposals. Raw SQL from a model is rejected.</p></div></template>
<template v-else-if="section==='widget'"><div class="widget-editor"><section class="panel settings-form"><h2>A distinctive first hello.</h2><label>Welcome title<input v-model="config.widget.title" maxlength="80" :disabled="!canEdit"/></label><label>Subtitle<input v-model="config.widget.subtitle" maxlength="180" :disabled="!canEdit"/></label><label>Launcher label<input v-model="config.widget.launcher" maxlength="60" :disabled="!canEdit"/></label><label>Theme<div class="theme-swatches"><button type="button" v-for="(color,name) in colors" :key="name" :style="{background:color}" :aria-label="name+' theme'" :aria-pressed="config.widget.theme===name" :disabled="!canEdit" @click="config.widget.theme=name as any"><Icon v-if="config.widget.theme===name" name="check" :size="18"/></button></div></label><div class="form-row"><label>Position<select v-model="config.widget.position" :disabled="!canEdit"><option value="right">Bottom right</option><option value="left">Bottom left</option></select></label><label>Corner radius (px)<input type="number" min="0" max="28" v-model.number="config.widget.radius" :disabled="!canEdit"/></label></div><div class="setting-row"><div><strong>Sahdev branding</strong><p>Removing branding requires an eligible plan.</p></div><Toggle v-model="config.widget.showBranding" label="Show Sahdev branding" :disabled="!canEdit"/></div><label>Allowed website origins<textarea v-model="origins" rows="3" placeholder="https://example.com" :disabled="!canEdit"/><small>One exact origin per line, with no trailing slash. No wildcard CORS.</small></label></section><div class="widget-preview-area"><span class="eyebrow">LIVE APPEARANCE PREVIEW</span><div class="widget-preview" :style="{'--widget-accent':colors[config.widget.theme],borderRadius:config.widget.radius+'px'}"><header><span class="widget-mark">✳</span><h2>{{config.widget.title}}</h2><p>{{config.widget.subtitle}}</p><small><span class="live-dot"></span>Human support · AI not connected</small></header><div class="widget-preview-body"><div class="widget-greeting">Hi there! Tell us a little about what you need help with.<small>{{config.assistantName}} · Preview</small></div><div class="widget-quick"><span>Ask a question <Icon name="arrow" :size="14"/></span><span>Find a helpful guide <Icon name="book" :size="14"/></span></div></div><div class="widget-preview-compose">Write your message…<span>↑</span></div><footer v-if="config.widget.showBranding">A more human conversation · Sahdev</footer></div><div class="widget-preview-launcher" :style="{background:colors[config.widget.theme],alignSelf:config.widget.position==='right'?'flex-end':'flex-start'}"><Icon name="chat" :size="18"/>{{config.widget.launcher}}</div></div></div><section class="panel config-card mt-6"><div class="flex justify-between items-center gap-4"><h2>Install on your website</h2><button class="button secondary small" @click="copyEmbed"><Icon name="copy" :size="14"/>Copy snippet</button></div><pre class="embed-snippet">{{embed}}</pre><p class="tiny-note">Save an allowed origin before installing. Each visitor gets a separate expiring session; entering an email does not verify account ownership. External embedding requires a publicly reachable deployment; the private Sites preview is protected by ChatGPT sign-in.</p></section></template>
<Modal :open="!!modal" @update:open="!$event&&(modal='')" :title="modal==='key'?'Store a provider credential':modal==='brain'?'Review customer memory':'Add trusted context'" :description="modal==='key'?'The credential is encrypted on the server and is never returned to the browser. Save the provider connection first.':undefined"><form v-if="modal==='key'" class="modal-form" @submit.prevent="saveKey"><label>API key<input type="password" v-model="key" autocomplete="new-password" required minlength="8" maxlength="5000"/></label><p class="tiny-note">An encryption key must be configured by the platform operator before credentials can be saved. No provider call is made by this action.</p><p v-if="error" class="form-error mt-4">{{error}}</p><div class="modal-actions"><button type="button" class="button secondary" @click="modal='';key=''">Cancel</button><button class="button primary" :disabled="busy">Encrypt & save</button></div></form><form v-else-if="modal==='source'" class="modal-form" @submit.prevent="addSource"><label>Name<input v-model="source.name" required minlength="2" maxlength="100"/></label><div class="form-row"><label>Type<select v-model="source.kind"><option value="document">Document text</option><option value="website">Website</option><option value="database">Named database connection</option></select></label><label>Audience<select v-model="source.audience"><option value="public">Public knowledge</option><option value="internal">Internal team</option></select></label></div><template v-if="source.kind==='document'"><label>Import text file<input type="file" accept=".txt,.md" @change="readDocument"/></label><label>Document text<textarea v-model="source.content" required rows="7" maxlength="8000"/></label></template><label v-else>{{source.kind==='website'?'HTTPS website URL':'Connector connection name'}}<input v-model="source.location" required :type="source.kind==='website'?'url':'text'" :placeholder="source.kind==='website'?'https://example.com/help':'customer-database'"/></label><div v-if="source.kind!=='document'" class="info-box"><Icon name="help"/>This registers the source. No remote website or database is contacted until its connector is configured and authorized.</div><p v-if="error" class="form-error">{{error}}</p><div class="modal-actions"><button type="button" class="button secondary" @click="modal=''">Cancel</button><button class="button primary" :disabled="busy">{{source.kind==='document'?'Import as draft':'Register source'}}</button></div></form><form v-else-if="brain" class="modal-form" @submit.prevent="saveBrain"><label>Factual customer profile<textarea v-model="brain.summary" rows="4" maxlength="4000" :disabled="!canEdit"/></label><div class="setting-row"><div><strong>I reviewed this profile</strong><p>Exact model token validation is still required before inclusion.</p></div><Toggle v-model="brain.reviewed" label="Profile reviewed" :disabled="!canEdit"/></div><div v-for="event in brain.events" :key="event.id" class="memory-event"><span class="pill subtle">{{event.method}}</span><h3>{{event.title}}</h3><p>{{event.text}}</p><small>{{event.at}} · {{event.conversationId}}</small></div><p v-if="error" class="form-error">{{error}}</p><div class="modal-actions"><button type="button" class="button secondary" @click="modal=''">Close</button><button v-if="canEdit" class="button primary" :disabled="busy">Save reviewed profile</button></div></form></Modal>
</template>
